<template>
  <main class="container-fluid context-search-curation">
    <div class="d-flex flex-wrap justify-content-between align-items-center gap-2 mb-3">
      <div><h1 class="h3 mb-1">{{ $t('pool.ai-datasets') }}</h1><p class="text-muted mb-0">{{ $t('pool.ai-datasets-intro') }}</p></div>
      <router-link :to="{name: 'material'}" class="btn btn-outline-secondary">{{ $t('pool.back-to-materials') }}</router-link>
    </div>
    <div v-if="error" class="alert alert-danger" role="alert">{{ error }}</div>

    <section class="mb-4" :aria-label="$t('pool.ai-dataset-overview')">
      <div class="d-flex flex-wrap gap-2 align-items-stretch">
        <article v-for="dataset in datasets" :key="dataset.id" class="dataset-card card" :class="[purposeClass(dataset.purpose), {'dataset-card-active': activeDatasetId === dataset.id}]">
          <div class="card-body py-2 d-flex align-items-center gap-1">
            <button class="dataset-badge btn btn-sm" type="button" :class="purposeClass(dataset.purpose)" @click="selectDataset(dataset.id)" :aria-describedby="`dataset-progress-${dataset.id}`"><span aria-hidden="true">{{ purposeIcon(dataset.purpose) }}</span><span>{{ purposeLabel(dataset.purpose) }}</span><span class="visually-hidden">: {{ dataset.status }}</span></button>
            <span v-if="dataset.title" class="small">{{ dataset.title }}</span>
            <button v-if="activeDatasetId !== dataset.id" class="btn btn-sm dataset-select-icon ms-auto" type="button" :title="$t('pool.ai-dataset-select')" :aria-label="$t('pool.ai-dataset-select')" @click="selectDataset(dataset.id)"><span aria-hidden="true">→</span></button>
            <div :id="`dataset-progress-${dataset.id}`" class="dataset-tooltip" role="tooltip"><strong>{{ purposeLabel(dataset.purpose) }}: {{ statusLabel(dataset.status) }}</strong><div>{{ $t('pool.ai-dataset-progress', {materials: dataset.material_count, materialTarget: dataset.target_material_count, resources: dataset.resource_count, resourceTarget: dataset.target_resource_count}) }}</div><div class="progress mt-1" aria-hidden="true"><div class="progress-bar" :style="{width: `${progress(dataset)}%`}"></div></div><div class="small">{{ $t('pool.ai-dataset-remaining', {materials: dataset.materials_remaining, resources: dataset.resources_remaining}) }}</div><ul v-if="Object.keys(dataset.quotas).length" class="mb-0 ps-3 small"><li v-for="(quota, name) in dataset.quotas" :key="name">{{ quotaLabel(name) }}: {{ quota.actual }}/{{ quota.target }} ({{ quota.remaining }} {{ $t('pool.ai-dataset-open') }})</li></ul></div>
          </div>
        </article>
        <button v-for="purpose in availablePurposes" :key="purpose" class="btn btn-outline-primary" type="button" @click="createDataset(purpose)">{{ purposeIcon(purpose) }} {{ $t('pool.ai-dataset-create', {purpose: purposeLabel(purpose)}) }}</button>
      </div>
    </section>

    <section v-if="activeDataset" class="card mb-4"><div class="card-body"><div class="d-flex flex-wrap gap-2 justify-content-between align-items-center"><div><h2 class="h5 mb-1">{{ purposeIcon(activeDataset.purpose) }} {{ purposeLabel(activeDataset.purpose) }}</h2><p class="mb-0 text-muted">{{ $t('pool.ai-dataset-selected-help') }}</p></div><button v-if="activeDataset.status === 'ready'" class="btn btn-warning" type="button" @click="freezeDataset" :disabled="saving">{{ $t('pool.ai-dataset-freeze') }}</button></div><div class="row g-2 mt-2"><div class="col-md-4"><label class="form-label" for="private-reason">{{ $t('pool.ai-dataset-private-reason') }}</label><input id="private-reason" v-model="privateReason" class="form-control" :disabled="!includePrivate || !isMutable"></div><div class="col-md-4 d-flex align-items-end"><div class="form-check"><input id="include-private" v-model="includePrivate" class="form-check-input" type="checkbox" :disabled="!isMutable"><label for="include-private" class="form-check-label">{{ $t('pool.ai-dataset-include-private') }}</label></div></div><div class="col-md-4 d-flex align-items-end justify-content-md-end gap-2"><button class="btn btn-outline-primary" type="button" @click="previewSelection" :disabled="!isMutable || !hasSelection || previewing">{{ $t('pool.ai-dataset-preview') }}</button><button class="btn btn-primary" type="button" @click="assignSelection" :disabled="!isMutable || !hasSelection || saving || hasConflicts">{{ $t('pool.ai-dataset-assign') }}</button></div></div><div v-if="preview" class="alert mt-3 mb-0" :class="hasConflicts ? 'alert-warning' : 'alert-info'">{{ $t('pool.ai-dataset-preview-result', {materials: preview.counts.materials, resources: preview.counts.resources, excluded: preview.excluded_resource_count}) }}<span v-if="hasConflicts"> {{ $t('pool.ai-dataset-preview-conflicts', {count: preview.conflicts.length}) }}</span></div></div></section>

    <section class="card"><div class="card-body"><div class="row g-2 mb-3"><div class="col-lg-4"><label class="visually-hidden" for="candidate-search">{{ $t('pool.Search') }}</label><input id="candidate-search" v-model.trim="filters.search" class="form-control" :placeholder="$t('pool.ai-dataset-search-placeholder')" @keyup.enter="updateCandidateRoute(1)"></div><div class="col-sm-4 col-lg-2"><select v-model="filters.type" class="form-select" @change="updateCandidateRoute(1)"><option value="all">{{ $t('pool.ai-dataset-all-types') }}</option><option value="pdf">PDF</option><option value="text">Text</option></select></div><div class="col-sm-4 col-lg-2"><select v-model="filters.visibility" class="form-select" @change="updateCandidateRoute(1)"><option value="all">{{ $t('pool.ai-dataset-all-visibility') }}</option><option value="public">{{ $t('pool.ai-dataset-public') }}</option><option value="private">{{ $t('pool.ai-dataset-private') }}</option></select></div><div class="col-sm-4 col-lg-2"><select v-model="filters.bundle" class="form-select" @change="updateCandidateRoute(1)"><option value="all">{{ $t('pool.ai-dataset-all-bundles') }}</option><option value="user">{{ $t('pool.ai-dataset-user-materials') }}</option><option v-for="bundle in candidates.bundles" :key="bundle.id" :value="String(bundle.id)">{{ bundle.name }}</option></select></div><div class="col-lg-2"><button class="btn btn-outline-secondary w-100" type="button" @click="updateCandidateRoute(1)">{{ $t('pool.Search') }}</button></div></div><p class="small text-muted">{{ $t('pool.ai-dataset-closure-notice') }}</p>
      <div class="row g-3"><aside class="col-lg-4" :aria-label="$t('pool.ai-dataset-material-preview')"><div v-if="previewMaterial" class="card preview-sidebar"><div class="preview-image-shell"><img :src="materialPreviewImage(previewMaterial.id)" class="card-img-top" :alt="$t('pool.ai-dataset-material-preview-image', {title: previewMaterial.title})"><div class="preview-image-actions"><button class="btn btn-sm btn-light" type="button" :title="$t('pool.ai-dataset-preview-material')" :aria-label="$t('pool.ai-dataset-preview-material')" @click="showMaterialPreview(previewMaterial)"><span aria-hidden="true">◉</span></button><router-link :to="{name: 'material-detail', params: {id: previewMaterial.id}}" target="_blank" class="btn btn-sm btn-light" :title="$t('pool.open')" :aria-label="$t('pool.open')"><span aria-hidden="true">↗</span></router-link></div></div><div class="card-body"><h2 class="h5">{{ previewMaterial.title }}</h2><p class="small text-muted mb-0">{{ previewMaterial.description || $t('pool.ai-dataset-no-description') }}</p></div></div><div v-else class="alert alert-light border">{{ $t('pool.ai-dataset-material-preview-empty') }}</div></aside><div class="col-lg-8"><div v-if="loading" class="text-muted">{{ $t('pool.Loading-resource') }}</div><div v-else class="list-group"><article v-for="material in candidates.data" :key="material.id" class="list-group-item candidate-item" :class="{'candidate-active': previewMaterial?.id === material.id}" @click="setPreviewMaterial(material)"><div class="d-flex gap-2 align-items-start"><input :id="`material-${material.id}`" :checked="isSelected(selectedMaterialIds, material.id)" class="form-check-input mt-1" type="checkbox" :disabled="!canSelect(material.assignment)" @click.prevent.stop="toggleMaterialSelection(material)"><div class="flex-grow-1"><div class="d-flex flex-wrap align-items-center gap-1"><label :for="`material-${material.id}`" class="fw-semibold" @click.prevent.stop="toggleMaterialSelection(material)">{{ material.title }}</label><button class="btn btn-outline-primary btn-sm py-0" type="button" :title="$t('pool.ai-dataset-preview-material')" :aria-label="$t('pool.ai-dataset-preview-material')" @click.stop="showMaterialPreview(material)"><span aria-hidden="true">◉</span></button><router-link :to="{name: 'material-detail', params: {id: material.id}}" target="_blank" class="btn btn-outline-secondary btn-sm py-0" :title="$t('pool.open')" :aria-label="$t('pool.open')" @click.stop><span aria-hidden="true">↗</span></router-link><span v-if="material.assignment" class="badge text-bg-secondary ms-auto" :title="$t('pool.ai-dataset-assignment-state', {dataset: assignmentDataset(material.assignment)?.title || purposeLabel(material.assignment.purpose), status: statusLabel(material.assignment.status)})"><span aria-hidden="true">🔒</span> {{ assignmentDataset(material.assignment)?.title || purposeLabel(material.assignment.purpose) }}</span><button v-if="canRemove(material.assignment)" class="btn btn-outline-danger btn-sm py-0" type="button" @click.stop="removeAssignment('material', material.id)">{{ $t('pool.ai-dataset-remove-block') }}</button><button v-else-if="isSelected(selectedMaterialIds, material.id) && material.resources.length > 2" class="btn btn-outline-secondary btn-sm py-0" type="button" @click.stop="clearMaterialSelection(material)">{{ $t('pool.ai-dataset-clear-block') }}</button></div><div v-if="isAssignedElsewhere(material.assignment)" class="alert alert-warning py-1 px-2 my-2 d-flex flex-wrap align-items-center gap-2" role="note" @click.stop><span aria-hidden="true">🔒</span><span>{{ $t('pool.ai-dataset-assigned-elsewhere', {dataset: assignmentDataset(material.assignment)?.title || purposeLabel(material.assignment.purpose), status: statusLabel(material.assignment.status)}) }}</span><button v-if="assignmentDataset(material.assignment)" class="btn btn-sm btn-outline-dark" type="button" @click="selectDataset(material.assignment.id)">{{ $t('pool.ai-dataset-open-owner') }}</button></div><div v-else-if="material.assignment" class="alert alert-info py-1 px-2 my-2" role="note" @click.stop>{{ $t('pool.ai-dataset-assigned-current') }}</div><p v-if="material.description" class="small mb-1 text-muted">{{ material.description }}</p><div v-for="resource in material.resources" :key="resource.id" class="form-check small ms-1"><input :id="`resource-${resource.id}`" :checked="isSelected(selectedResourceIds, resource.id)" class="form-check-input" type="checkbox" :disabled="!canSelect(resource.assignment)" @click.prevent.stop="toggleResourceSelection(resource, material)"><label :for="`resource-${resource.id}`" class="form-check-label" @click.prevent.stop="toggleResourceSelection(resource, material)">{{ resource.type.toUpperCase() }} · {{ resource.notes || $t('pool.Resource') }} <span class="text-muted">({{ resource.is_public ? $t('pool.ai-dataset-public') : $t('pool.ai-dataset-private') }})</span></label><button class="btn btn-link btn-sm py-0" type="button" :title="$t('pool.ai-dataset-preview-resource')" :aria-label="$t('pool.ai-dataset-preview-resource')" @click.stop="showResourcePreview(resource, material)"><span aria-hidden="true">◉</span></button><router-link :to="{name: 'resource-detail', params: {id: resource.id}}" target="_blank" class="btn btn-link btn-sm py-0" :title="$t('pool.open')" :aria-label="$t('pool.open')" @click.stop><span aria-hidden="true">↗</span></router-link><span v-if="resource.assignment" class="badge" :class="isAssignedElsewhere(resource.assignment) ? 'text-bg-warning' : 'text-bg-info'" role="note" :title="$t('pool.ai-dataset-assignment-state', {dataset: assignmentDataset(resource.assignment)?.title || purposeLabel(resource.assignment.purpose), status: statusLabel(resource.assignment.status)})"><span aria-hidden="true">🔒</span> {{ $t(isAssignedElsewhere(resource.assignment) ? 'pool.ai-dataset-assigned-elsewhere-short' : 'pool.ai-dataset-assigned-current-short', {dataset: assignmentDataset(resource.assignment)?.title || purposeLabel(resource.assignment.purpose)}) }}</span><button v-if="canRemove(resource.assignment)" class="btn btn-link btn-sm py-0 text-danger" type="button" @click.stop="removeAssignment('resource', resource.id)">{{ $t('pool.remove') }}</button></div></div></div></article></div></div></div>
      <nav v-if="candidates.last_page > 1" class="mt-3" :aria-label="$t('pool.ai-dataset-pages')"><div class="btn-group"><button class="btn btn-outline-secondary" type="button" :disabled="candidates.current_page <= 1" :title="$t('pool.ai-dataset-first-page')" @click="updateCandidateRoute(1)">«</button><button class="btn btn-outline-secondary" type="button" :disabled="candidates.current_page <= 1" :title="$t('pool.ai-dataset-previous-page')" @click="updateCandidateRoute(Math.max(1, candidates.current_page - 10))">‹‹</button><button class="btn btn-outline-secondary" type="button" :disabled="candidates.current_page <= 1" :title="$t('pool.ai-dataset-previous-page')" @click="updateCandidateRoute(candidates.current_page - 1)">‹</button><span class="btn btn-outline-secondary disabled">{{ candidates.current_page }} / {{ candidates.last_page }}</span><button class="btn btn-outline-secondary" type="button" :disabled="candidates.current_page >= candidates.last_page" :title="$t('pool.ai-dataset-next-page')" @click="updateCandidateRoute(candidates.current_page + 1)">›</button><button class="btn btn-outline-secondary" type="button" :disabled="candidates.current_page >= candidates.last_page" :title="$t('pool.ai-dataset-next-page')" @click="updateCandidateRoute(Math.min(candidates.last_page, candidates.current_page + 10))">››</button><button class="btn btn-outline-secondary" type="button" :disabled="candidates.current_page >= candidates.last_page" :title="$t('pool.ai-dataset-last-page')" @click="updateCandidateRoute(candidates.last_page)">»</button></div></nav>
    </div></section>
    <b-modal ref="materialPreviewModal" size="xl" scrollable hide-footer :title="previewModalTitle"><div v-if="modalMaterial" class="row g-3"><div class="col-lg-4"><img :src="materialPreviewImage(modalMaterial.id)" class="img-fluid border" :alt="$t('pool.ai-dataset-material-preview-image', {title: modalMaterial.title})"><h2 class="h5 mt-2">{{ modalMaterial.title }}</h2><p>{{ modalMaterial.description || $t('pool.ai-dataset-no-description') }}</p><router-link :to="{name: 'material-detail', params: {id: modalMaterial.id}}" target="_blank" class="btn btn-outline-secondary btn-sm">{{ $t('pool.open') }}</router-link></div><div class="col-lg-8"><div class="list-group mb-3"><div v-for="resource in modalMaterial.resources" :key="resource.id" class="list-group-item d-flex justify-content-between gap-2" :class="{'active': modalResourceId === resource.id}"><button type="button" class="btn btn-link p-0 text-start flex-grow-1" :class="{'text-white': modalResourceId === resource.id}" @click="loadModalResource(resource)">{{ resource.type.toUpperCase() }} · {{ resource.notes || $t('pool.Resource') }}</button><router-link :to="{name: 'resource-detail', params: {id: resource.id}}" target="_blank" class="btn btn-sm btn-outline-secondary" @click.stop>{{ $t('pool.open') }}</router-link></div></div><div v-if="modalResourceLoading" class="text-muted">{{ $t('pool.Loading-resource') }}</div><resource-preview v-else-if="modalResource" :resource="modalResource" :max-preview-pages="modalResource.page_count || 15" :show-download="false" :show-open="false" /></div></div></b-modal>
  </main>
</template>

<script>
import axios from '../axiosInstance';
import {useGeneralStore} from '../stores/general';
import {BModal} from '@/adapters/bootstrap';
import ResourcePreview from '../../../components/resource/show/resource-preview.vue';
import {material_preview_image} from '../../../components/serverRoutes';

const DatasetAssignmentBadge = {props: {assignment: {type: Object, required: true}}, methods: {icon(purpose) { return ({calibration: '◉', acceptance: '✓', ocr: '⌁', load: '◌', capacity: '▣'})[purpose] || '•'; }}, template: '<span class="badge text-bg-secondary" :title="`${assignment.title || assignment.purpose} · ${assignment.status}`"><span aria-hidden="true">{{ icon(assignment.purpose) }}</span> {{ assignment.title || assignment.purpose }}</span>'};

export default {
  name: 'ContextSearchEvaluationDatasets', components: {BModal, DatasetAssignmentBadge, ResourcePreview},
  data() { return {datasets: [], candidates: {data: [], bundles: [], current_page: 1, last_page: 1}, filters: {search: '', type: 'all', visibility: 'all', bundle: 'all'}, activeDatasetId: null, selectedMaterialIds: [], selectedResourceIds: [], includePrivate: false, privateReason: '', preview: null, previewMaterial: null, modalMaterial: null, modalResource: null, modalResourceId: null, modalResourceLoading: false, loading: false, previewing: false, saving: false, error: ''}; },
  computed: {activeDataset() { return this.datasets.find(dataset => dataset.id === this.activeDatasetId) || null; }, isMutable() { return ['draft', 'ready'].includes(this.activeDataset?.status); }, hasSelection() { return this.selectedMaterialIds.length > 0 || this.selectedResourceIds.length > 0; }, hasConflicts() { return (this.preview?.conflicts?.length || 0) > 0; }, previewModalTitle() { return this.modalMaterial ? this.$t('pool.ai-dataset-preview-material-title', {title: this.modalMaterial.title}) : ''; }, availablePurposes() { return ['calibration', 'acceptance', 'ocr', 'load', 'capacity'].filter(purpose => !this.datasets.some(dataset => dataset.purpose === purpose && ['draft', 'ready'].includes(dataset.status))); }},
  watch: {activeDatasetId(datasetId) { const dataset = this.datasets.find(item => item.id === datasetId); this.includePrivate = Boolean(dataset?.includes_private); this.privateReason = dataset?.private_reason || ''; this.clearSelection(); }, '$route.query': {handler() { this.applyCandidateRoute(); }, deep: true}},
  async created() { const user = await useGeneralStore().currentUser(); if (!user?.is_admin) return this.$router.replace({name: 'material'}); await this.loadDatasets(); this.applyCandidateRoute(); },
  methods: {
    purposeIcon(purpose) { return ({calibration: '◉', acceptance: '✓', ocr: '⌁', load: '◌', capacity: '▣'})[purpose] || '•'; }, purposeLabel(purpose) { return this.$t(`pool.ai-dataset-purpose-${purpose}`); }, purposeClass(purpose) { return `dataset-${purpose}`; }, statusLabel(status) { return this.$t(`pool.ai-dataset-status-${status}`); }, quotaLabel(name) { return this.$t(`pool.ai-dataset-quota-${name}`); }, progress(dataset) { const target = Math.max(1, dataset.target_resource_count || 1); return Math.min(100, Math.round((dataset.resource_count / target) * 100)); }, isSelected(ids, id) { return ids.includes(id); }, canSelect(assignment) { return this.isMutable && !assignment; }, canRemove(assignment) { return this.isMutable && assignment?.id === this.activeDatasetId; }, isAssignedElsewhere(assignment) { return Boolean(assignment && assignment.id !== this.activeDatasetId); }, assignmentDataset(assignment) { return this.datasets.find(dataset => dataset.id === assignment?.id) || null; },
    candidateQuery(page) { return {dataset: this.activeDatasetId || undefined, page, search: this.filters.search || undefined, type: this.filters.type !== 'all' ? this.filters.type : undefined, visibility: this.filters.visibility !== 'all' ? this.filters.visibility : undefined, bundle: this.filters.bundle !== 'all' ? this.filters.bundle : undefined}; },
    applyCandidateRoute() { const query = this.$route.query; this.filters = {search: query.search || '', type: query.type || 'all', visibility: query.visibility || 'all', bundle: query.bundle || 'all'}; this.loadCandidates(Math.max(1, Number.parseInt(query.page, 10) || 1)); }, updateCandidateRoute(page) { this.$router.push({name: 'context-search-evaluation-datasets', query: this.candidateQuery(page)}); }, selectDataset(datasetId) { this.activeDatasetId = datasetId; this.$router.replace({name: 'context-search-evaluation-datasets', query: this.candidateQuery(this.candidates.current_page || 1)}); },
    async loadDatasets() { try { const {data} = await axios.get('/api/v2/admin/context-search/datasets'); this.datasets = data.datasets; const routeDatasetId = this.$route.query.dataset; if (this.datasets.some(dataset => String(dataset.id) === String(routeDatasetId))) this.activeDatasetId = routeDatasetId; else if (!this.activeDatasetId && this.datasets.length) this.activeDatasetId = this.datasets.find(dataset => dataset.status === 'draft')?.id || this.datasets[0].id; } catch (error) { this.error = error.response?.data?.message || error.message; } },
    async loadCandidates(page) { this.loading = true; try { const {data} = await axios.get('/api/v2/admin/context-search/datasets/candidates', {params: {...this.filters, page}}); this.candidates = data; this.previewMaterial = data.data.find(material => material.id === this.previewMaterial?.id) || data.data[0] || null; } catch (error) { this.error = error.response?.data?.message || error.message; } finally { this.loading = false; } }, async createDataset(purpose) { try { const {data} = await axios.post('/api/v2/admin/context-search/datasets', {purpose}); this.datasets.push(data.dataset); this.selectDataset(data.dataset.id); } catch (error) { this.error = error.response?.data?.message || error.message; } },
    clearPreview() { this.preview = null; }, clearSelection() { this.selectedMaterialIds = []; this.selectedResourceIds = []; this.preview = null; }, addSelection(ids, id) { if (!ids.includes(id)) ids.push(id); }, removeSelection(ids, id) { const index = ids.indexOf(id); if (index >= 0) ids.splice(index, 1); }, toggleMaterialSelection(material) { if (!this.canSelect(material.assignment)) return; this.setPreviewMaterial(material); if (this.isSelected(this.selectedMaterialIds, material.id)) this.clearMaterialSelection(material); else { this.addSelection(this.selectedMaterialIds, material.id); material.resources.filter(resource => this.canSelect(resource.assignment)).forEach(resource => this.addSelection(this.selectedResourceIds, resource.id)); this.clearPreview(); } }, clearMaterialSelection(material) { this.removeSelection(this.selectedMaterialIds, material.id); material.resources.forEach(resource => this.removeSelection(this.selectedResourceIds, resource.id)); this.clearPreview(); }, toggleResourceSelection(resource, material) { if (!this.canSelect(resource.assignment)) return; this.setPreviewMaterial(material); if (this.isSelected(this.selectedResourceIds, resource.id)) this.removeSelection(this.selectedResourceIds, resource.id); else this.addSelection(this.selectedResourceIds, resource.id); this.clearPreview(); }, materialPreviewImage(materialId) { return material_preview_image(materialId); }, setPreviewMaterial(material) { this.previewMaterial = material; },
    async showMaterialPreview(material) { this.modalMaterial = material; this.modalResource = null; this.modalResourceId = null; this.$refs.materialPreviewModal.show(); if (material.resources.length) await this.loadModalResource(material.resources[0]); }, async showResourcePreview(resource, material) { this.modalMaterial = material; this.modalResource = null; this.modalResourceId = null; this.$refs.materialPreviewModal.show(); await this.loadModalResource(resource); }, async loadModalResource(resource) { this.modalResourceId = resource.id; this.modalResource = null; this.modalResourceLoading = true; try { const {data} = await axios.get(`/api/v1/resources/${resource.id}`); this.modalResource = data; } catch (error) { this.error = error.response?.data?.message || error.message; } finally { this.modalResourceLoading = false; } },
    async previewSelection() { this.previewing = true; this.error = ''; try { const {data} = await axios.post('/api/v2/admin/context-search/datasets/preview', {material_ids: this.selectedMaterialIds, resource_ids: this.selectedResourceIds}); this.preview = data.preview; } catch (error) { this.error = error.response?.data?.message || error.message; } finally { this.previewing = false; } }, async assignSelection() { if (!this.preview) await this.previewSelection(); if (this.hasConflicts || !this.preview) return; this.saving = true; this.error = ''; try { const {data} = await axios.post(`/api/v2/admin/context-search/datasets/${this.activeDataset.id}/assign`, {material_ids: this.selectedMaterialIds, resource_ids: this.selectedResourceIds, expected_version: this.activeDataset.version, include_private: this.includePrivate, private_reason: this.privateReason || null}); this.replaceDataset(data.dataset); this.clearSelection(); await this.loadCandidates(this.candidates.current_page); } catch (error) { this.error = error.response?.data?.message || error.message; await this.loadDatasets(); } finally { this.saving = false; } }, async removeAssignment(memberType, memberId) { if (!window.confirm(this.$t('pool.ai-dataset-remove-confirm'))) return; this.saving = true; this.error = ''; try { const {data} = await axios.delete(`/api/v2/admin/context-search/datasets/${this.activeDataset.id}/members/${memberType}/${memberId}`, {params: {expected_version: this.activeDataset.version}}); this.replaceDataset(data.dataset); this.clearSelection(); await this.loadCandidates(this.candidates.current_page); } catch (error) { this.error = error.response?.data?.message || error.message; await this.loadDatasets(); } finally { this.saving = false; } }, async freezeDataset() { this.saving = true; try { const {data} = await axios.post(`/api/v2/admin/context-search/datasets/${this.activeDataset.id}/freeze`); this.replaceDataset(data.dataset); await this.loadCandidates(this.candidates.current_page); } catch (error) { this.error = error.response?.data?.message || error.message; } finally { this.saving = false; } }, replaceDataset(dataset) { const index = this.datasets.findIndex(item => item.id === dataset.id); if (index >= 0) this.datasets.splice(index, 1, dataset); },
  },
};
